<script lang="ts">
 import {untrack,tick,onMount} from 'svelte';
 import type {Snippet} from 'svelte';
 import MarkdownView from '$lib/components/MarkdownView.svelte';
 import {photoFileProblem} from '$lib/content-blocks';
 let {value=$bindable(''),name='body',facilityId,disabled=false,onBusy=(_busy:boolean)=>{},onSave=()=>{},onToolbar}:{value?:string;name?:string;facilityId:string;disabled?:boolean;onBusy?:(busy:boolean)=>void;onSave?:()=>void;onToolbar?:(tools:Snippet|undefined)=>void}=$props();
 let area:HTMLTextAreaElement,fileInput:HTMLInputElement;
 let mode=$state<'edit'|'split'|'preview'>('edit'),uploading=$state(false),dragging=$state(false),error=$state('');
 let linkPanel=$state(false),linkUrl=$state('https://'),linkText=$state(''),imagePanel=$state(false),imageAlt=$state('');
 let ctaPanel=$state(false),ctaLabel=$state('宿泊プラン・空室を確認'),ctaUrl=$state('https://www.yamado.co.jp/reservation/'),ctaStyle=$state('cta');
 let selection={start:0,end:0},history=$state<string[]>([untrack(()=>value)]),position=$state(0);
 const locked=$derived(disabled||uploading);
 onMount(()=>{onToolbar?.(toolbar);return()=>onToolbar?.(undefined);});
 $effect(()=>{void value;void mode;if(!area||CSS.supports('field-sizing','content'))return;const field=area;const resize=()=>{field.style.height='auto';field.style.height=Math.max(420,field.scrollHeight)+'px';};let width=0;const observer=new ResizeObserver(([entry])=>{if(entry.contentRect.width!==width){width=entry.contentRect.width;resize();}});observer.observe(field.parentElement!);resize();return()=>observer.disconnect();});
 function remember(){if(area)selection={start:area.selectionStart??value.length,end:area.selectionEnd??value.length};}
 function change(next:string){if(next===value&&history[position]===next)return;history=[...history.slice(0,position+1),next].slice(-100);position=history.length-1;value=next;}
 async function replace(before:string,after='',placeholder=''){
  remember();const {start,end}=selection,selected=value.slice(start,end)||placeholder;
  change(value.slice(0,start)+before+selected+after+value.slice(end));
  await tick();area?.focus();area?.setSelectionRange(start+before.length,start+before.length+selected.length);remember();
 }
 async function insertAt(text:string,start=selection.start,end=selection.end){change(value.slice(0,start)+text+value.slice(end));await tick();area?.focus();area?.setSelectionRange(start+text.length,start+text.length);remember();}
 function prefix(mark:string){remember();const start=value.lastIndexOf('\n',Math.max(0,selection.start-1))+1;const stop=value.indexOf('\n',selection.end);const end=stop<0?value.length:stop;void insertAt(value.slice(start,end).split('\n').map((line,index)=>mark==='#number'?`${index+1}. ${line}`:mark+line).join('\n'),start,end);}
 async function undo(step:number){const next=position+step;if(next<0||next>=history.length)return;position=next;value=history[position];await tick();area?.focus();remember();}
 function openLink(){remember();linkText=value.slice(selection.start,selection.end);linkUrl='https://';linkPanel=!linkPanel;imagePanel=false;ctaPanel=false;}
 function openCta(){remember();const selected=value.slice(selection.start,selection.end).trim(),existing=/^\[([^\]]+)\]\((\S+?)(?: "(cta|cta-outline)")?\)$/.exec(selected);ctaLabel=existing?.[1]||'宿泊プラン・空室を確認';ctaUrl=existing?.[2]||(facilityId==='f-nishiwaga'?'https://www.yamado.co.jp/reservation/':'https://');ctaStyle=existing?.[3]||'cta';ctaPanel=!ctaPanel;linkPanel=false;imagePanel=false;error='';}
 function addCta(){const url=ctaUrl.trim(),label=ctaLabel.trim();if(!label||label.length>80){error='ボタンの文字は1〜80文字で入力してください。';return;}if(!/^(https?:\/\/|tel:|mailto:|\/(?!\/)|#)/i.test(url)||/[\s"<>]/.test(url)||url==='https://'||url==='http://'){error='ボタンのリンク先を正しく入力してください。';return;}const safeLabel=Array.from(label.replace(/[\r\n]/g,' ')).map(ch=>('\\[]*_'+String.fromCharCode(96)).includes(ch)?'\\'+ch:ch).join('');if(!safeLabel){error='ボタンの文字を入力してください。';return;}void insertAt('\n\n['+safeLabel+']('+url.replace(/\(/g,'%28').replace(/\)/g,'%29')+' "'+(ctaStyle==='cta-outline'?'cta-outline':'cta')+'")\n\n');ctaPanel=false;error='';}
 function addLink(){const url=linkUrl.trim();if(!/^(https?:\/\/|tel:|mailto:|\/(?!\/)|#)/i.test(url)||/[\r\n]/.test(url)){error='リンク先はhttps://などのURLを指定してください。';return;}const label=(linkText.trim()||'リンク').replace(/[\[\]\r\n]/g,' ');void insertAt(`[${label}](${url.replace(/\(/g,'%28').replace(/\)/g,'%29').replace(/ /g,'%20')})`);linkPanel=false;error='';}
 async function upload(files:File[]){
  if(locked||!files.length)return;if(files.length>8){error='一度に選択できる画像は8枚までです。';return;}
  for(const file of files){const problem=photoFileProblem(file);if(problem){error=problem;return;}}
  remember();const selected={...selection};uploading=true;onBusy(true);error='';const inserts:string[]=[];
  try{
   for(const file of files){const form=new FormData();form.set('file',file);form.set('facilityId',facilityId);const response=await fetch('/admin/news/images',{method:'POST',body:form,signal:AbortSignal.timeout(60000)});const result=await response.json();if(!response.ok)throw Error(result.error||'画像を追加できませんでした。');const alt=(imageAlt.trim()||file.name.replace(/\.[^.]+$/,'')).replace(/[\[\]\r\n]/g,' ').slice(0,120);inserts.push(`![${alt}](${result.url})`);}
  }catch(e){error=e instanceof Error?e.message:'画像を追加できませんでした。';}
  finally{uploading=false;onBusy(false);if(inserts.length)await insertAt('\n\n'+inserts.join('\n\n')+'\n\n',selected.start,selected.end);if(fileInput)fileInput.value='';imagePanel=false;imageAlt='';}
 }
 function drop(event:DragEvent){if(!event.dataTransfer?.files.length)return;event.preventDefault();dragging=false;void upload(Array.from(event.dataTransfer.files));}
 function paste(event:ClipboardEvent){const files=Array.from(event.clipboardData?.files??[]).filter(f=>f.type.startsWith('image/'));if(files.length){event.preventDefault();void upload(files);}}
 function shortcuts(event:KeyboardEvent){if(!(event.ctrlKey||event.metaKey))return;const key=event.key.toLowerCase();if(key==='s'){event.preventDefault();onSave();}else if(key==='b'){event.preventDefault();void replace('**','**','太字');}else if(key==='i'){event.preventDefault();void replace('*','*','斜体');}else if(key==='k'){event.preventDefault();openLink();}else if(key==='z'){event.preventDefault();void undo(event.shiftKey?1:-1);}else if(key==='y'){event.preventDefault();void undo(1);}}
</script>

{#snippet toolbar()}
<div class="source-tools">
 <div class="editor-head"><span>本文 <small>Markdown</small></span><nav aria-label="エディタの表示切り替え">{#each [{id:'edit',label:'編集'},{id:'split',label:'分割'},{id:'preview',label:'プレビュー'}] as tab}<button type="button" class:active={mode===tab.id} aria-pressed={mode===tab.id} onclick={()=>mode=tab.id as typeof mode}>{tab.label}</button>{/each}</nav></div>
 <div class="editor-toolbar" role="toolbar" aria-label="本文の書式">
  <button type="button" disabled={locked||position===0} aria-label="元に戻す" title="元に戻す（Ctrl+Z）" onclick={()=>void undo(-1)}>↶</button><button type="button" disabled={locked||position===history.length-1} aria-label="やり直す" title="やり直す（Ctrl+Shift+Z）" onclick={()=>void undo(1)}>↷</button><span class="separator"></span>
  <button type="button" disabled={locked} title="見出し2" onclick={()=>prefix('## ')}>H2</button><button type="button" disabled={locked} title="見出し3" onclick={()=>prefix('### ')}>H3</button><button type="button" disabled={locked} aria-label="太字" title="太字（Ctrl+B）" onclick={()=>void replace('**','**','太字')}><b>B</b></button><button type="button" disabled={locked} aria-label="斜体" title="斜体（Ctrl+I）" onclick={()=>void replace('*','*','斜体')}><i>I</i></button><span class="separator"></span>
  <button type="button" disabled={locked} onclick={()=>prefix('- ')}>箇条書き</button><button type="button" disabled={locked} onclick={()=>prefix('#number')}>番号リスト</button><button type="button" disabled={locked} onclick={()=>prefix('> ')}>引用</button><button type="button" disabled={locked} onclick={()=>{remember();void insertAt('\n\n---\n\n');}}>区切り線</button><button type="button" disabled={locked} onclick={()=>{remember();void insertAt('\n\n| 項目 | 内容 |\n| --- | --- |\n|  |  |\n\n');}}>表</button>
  <button type="button" disabled={locked} aria-pressed={linkPanel} onclick={openLink}>リンク</button><button type="button" disabled={locked} aria-pressed={imagePanel} onclick={()=>{remember();imagePanel=!imagePanel;linkPanel=false;ctaPanel=false;}}>画像を挿入</button><button type="button" class="cta-tool" disabled={locked} aria-pressed={ctaPanel} onclick={openCta}>CTAボタン</button>
 </div>
 {#if linkPanel}<div class="insert-panel"><label>リンクの文字<input bind:value={linkText} placeholder="表示する文字"/></label><label>リンク先URL<input bind:value={linkUrl} placeholder="https://"/></label><button type="button" onclick={addLink}>挿入</button><button type="button" onclick={()=>linkPanel=false}>閉じる</button></div>{/if}
 {#if imagePanel}<div class="insert-panel"><label>画像の説明（代替テキスト）<input bind:value={imageAlt} maxlength="120" placeholder="例：クリスマスディナーの前菜"/></label><button type="button" disabled={locked} onclick={()=>fileInput.click()}>画像を選択</button><span>JPEG・PNG・WebP・AVIF／1枚10MBまで</span><button type="button" onclick={()=>imagePanel=false}>閉じる</button></div>{/if}
 {#if ctaPanel}<div class="insert-panel cta-panel"><label>ボタンの文字<input bind:value={ctaLabel} maxlength="80" placeholder="例：宿泊プラン・空室を確認" disabled={locked}/></label><label>ボタンのリンク先<input bind:value={ctaUrl} placeholder="https://" disabled={locked}/></label><label class="cta-style">テンプレート<select bind:value={ctaStyle} disabled={locked}><option value="cta">塗りつぶし</option><option value="cta-outline">枠線</option></select></label><button type="button" disabled={locked} onclick={addCta}>ボタンを挿入</button><button type="button" onclick={()=>ctaPanel=false}>閉じる</button></div>{/if}
</div>
{/snippet}
<section class="news-markdown" class:drag-over={dragging} aria-label="本文マークダウンエディタ">
 {#if !onToolbar}{@render toolbar()}{/if}
 <input class="file-input" tabindex="-1" bind:this={fileInput} type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple aria-label="挿入する画像を選択" onchange={event=>void upload(Array.from(event.currentTarget.files??[]))}/>
 <div class="editor-panes" class:split={mode==='split'} role="group" aria-label="本文の編集領域" ondragover={event=>{if(Array.from(event.dataTransfer?.types??[]).includes('Files')){event.preventDefault();dragging=true;}}} ondragleave={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node))dragging=false;}} ondrop={drop}>
  <textarea bind:this={area} value={value} {name} aria-label="お知らせ本文" onkeydown={shortcuts} maxlength="100000" spellcheck="false" disabled={locked} oninput={event=>change(event.currentTarget.value)} onselect={remember} onkeyup={remember} onclick={remember} onpaste={paste} class:off={mode==='preview'} placeholder="本文を入力してください。画像はドラッグ＆ドロップでも追加できます。"></textarea>
  <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable preview needs keyboard focus.) -->
  <div class="editor-preview" class:off={mode==='edit'} role="region" tabindex="0" aria-label="本文プレビュー">{#if value.trim()}<MarkdownView source={value} news/>{:else}<p class="empty-preview">本文のプレビューが表示されます。</p>{/if}</div>
 </div>
 <div class="editor-status" aria-live="polite"><span>{uploading?'画像をアップロード中…':dragging?'画像をドロップして挿入':'画像のドラッグ＆ドロップ・貼り付けに対応'}</span><span>{value.length.toLocaleString()}文字</span></div>
 {#if error}<p class="editor-error" role="alert">{error}</p>{/if}
</section>
<style>
.news-markdown{background:#fff;color:#354937;min-width:0}.source-tools{position:relative}.editor-head{display:flex;justify-content:flex-end;align-items:center;gap:.8rem;padding:.7rem 1rem;border-bottom:1px solid #e5eadf;background:#fcfdf9}.editor-head>span{display:none}.editor-head small{font-size:.65rem;color:#98a28c;font-weight:400;margin-left:.5rem}.editor-head nav{display:flex;margin-left:auto;gap:.2rem;background:#f0f3eb;padding:.2rem;border-radius:.5rem}.editor-head button{font-size:.7rem;padding:.35rem .65rem;border-radius:.35rem;color:#87927c}.editor-head button.active{background:#fff;box-shadow:0 1px 4px #30462c14;color:#4f6d40}.editor-toolbar{display:flex;justify-content:flex-end;flex-wrap:wrap;align-items:center;gap:.2rem;padding:.55rem .7rem;border-bottom:1px solid #e4eadd}.editor-toolbar button{padding:.35rem .55rem;font-size:.74rem;border:1px solid transparent;border-radius:.4rem;min-height:31px;color:#6a7d5b;transition:background .15s,border-color .15s}.editor-toolbar button:hover:not(:disabled){background:#edf3e5;border-color:#d6e1cb;color:#3d5c2c}.editor-toolbar button:disabled{opacity:.32;cursor:default}.separator{height:18px;width:1px;background:#e3e8dc;margin:0 .25rem}.insert-panel{display:flex;align-items:flex-end;flex-wrap:wrap;gap:.7rem;padding:.85rem 1rem;background:#f5f8ef;border-bottom:1px solid #e2e9d9}.insert-panel label{display:grid;gap:.3rem;font-size:.7rem;color:#7c8c6e;flex:1;min-width:180px}.insert-panel select{border:1px solid #dce4d2;border-radius:.4rem;padding:.5rem .65rem;font-size:.78rem;background:#fff;color:#3e5731}.insert-panel .cta-style{flex:0 1 130px;min-width:120px}.editor-toolbar .cta-tool{border-color:#c7c0ac;background:#f4f1e9;color:#665b3e}.insert-panel input{border:1px solid #dce4d2;border-radius:.4rem;padding:.5rem .65rem;font-size:.78rem;background:#fff;color:#3e5731}.insert-panel button{border:1px solid #d3dec7;border-radius:.4rem;padding:.5rem .7rem;background:#fff;color:#688153;font-size:.72rem}.insert-panel button:hover{background:#e9f1df}.insert-panel>span{font-size:.65rem;color:#8c987f;align-self:center}.file-input{position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;pointer-events:none}.editor-panes{display:grid;align-items:start;min-height:420px;grid-template-rows:auto;overflow:visible}.editor-panes.split{grid-template-columns:1fr 1fr}.editor-panes textarea{field-sizing:content;display:block;width:100%;height:auto;min-height:420px;min-width:0;overflow:hidden;resize:none;border:0;outline:0;padding:1.2rem;font:13px/1.9 ui-monospace,SFMono-Regular,Consolas,monospace;color:#40513b;background:#fff;tab-size:2}.editor-panes textarea:focus{box-shadow:inset 0 0 0 2px #789c5f45}.editor-panes.split textarea{border-right:1px solid #e5ebde}.editor-preview{min-width:0;overflow:visible;padding:1.1rem 1.3rem;background:#fcfdf9;font-size:.85rem;line-height:1.9;min-height:0}.editor-preview :global(img){max-width:100%;height:auto}.editor-preview :global(blockquote){border-left:3px solid #b5c5a7;padding-left:1rem;margin:.8rem 0;color:#7a8d6a}.editor-preview :global(hr){margin:1.2rem 0;border-color:#dde5d4}.empty-preview{color:#a5af9b;font-size:.8rem}.editor-panes .off{display:none}.editor-status{display:flex;justify-content:space-between;gap:1rem;padding:.55rem .9rem;font-size:.65rem;color:#92a080;border-top:1px solid #e5ebde;background:#fafcf6}.editor-error{padding:.65rem 1rem;font-size:.75rem;color:#a56543;background:#fff3ec}.drag-over{outline:3px solid #86a868;outline-offset:2px}.editor-preview:focus-visible{outline:2px solid #809f68;outline-offset:-2px}button:focus-visible,input:focus-visible{outline:2px solid #809f68;outline-offset:2px}@media(max-width:800px){.editor-panes.split{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto}.editor-panes.split textarea{border-right:0}.editor-panes.split .editor-preview{border-top:1px solid #e0e7d6}.editor-panes{height:auto}.editor-toolbar{gap:0;padding:.4rem}.editor-toolbar button{font-size:.7rem;padding:.35rem .45rem}.editor-head{gap:.4rem;padding:.6rem}.editor-head small{display:none}.editor-status{font-size:.6rem}}
</style>
